head.b:skin:
/*
Variable definitions
====================
<Variable name="bg" description="Background" type="color" default="#f7f8fc" value="#f7f8fc"/>
<Variable name="ink" description="Text" type="color" default="#0f172a" value="#0f172a"/>
<Variable name="brand" description="Brand" type="color" default="#1e3a8a" value="#1e3a8a"/>
<Variable name="accent" description="Accent" type="color" default="#3b82f6" value="#3b82f6"/>
*/
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: 'Inter', system-ui, sans-serif; background: $(bg); color: $(ink); -webkit-font-smoothing: antialiased; }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }

.site-header { background: #fff; box-shadow: 0 1px 3px rgba(0,0,0,.04); position: sticky; top: 0; z-index: 10; }
.site-header .inner { max-width: 1100px; margin: 0 auto; padding: 16px 24px; display: flex; justify-content: space-between; align-items: center; }
.brand { font-family: 'Dancing Script', cursive; font-size: 26px; font-weight: 700; color: $(brand); }
.nav { display: flex; gap: 20px; font-size: 14px; }
.nav a:hover { color: $(brand); }

.hero { position: relative; min-height: 420px; padding: 80px 24px; background: linear-gradient(135deg, #e0e7ff 0%, #dbeafe 100%); }
.hero .inner { max-width: 1100px; margin: 0 auto; }
.hero h1 { font-size: 44px; line-height: 1.15; color: $(brand); max-width: 720px; font-weight: 700; }
.hero p { margin-top: 16px; max-width: 640px; color: #334155; font-size: 17px; line-height: 1.6; }

.wrap { max-width: 1100px; margin: 0 auto; padding: 48px 24px; }
.section-title { display: flex; align-items: center; gap: 12px; margin-bottom: 24px; }
.section-title::before { content: ''; display: inline-block; width: 6px; height: 26px; background: $(accent); border-radius: 3px; }
.section-title h2 { font-size: 26px; color: $(ink); }

.posts { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 22px; }
.post-card { background: #fff; border-radius: 14px; overflow: hidden; box-shadow: 0 4px 12px rgba(0,0,0,.05); transition: transform .15s; }
.post-card:hover { transform: translateY(-3px); }
.post-card .thumb { width: 100%; aspect-ratio: 16/10; object-fit: cover; background: #e2e8f0; }
.post-card .body { padding: 18px; }
.post-card .label { font-size: 12px; color: $(accent); font-weight: 600; text-transform: uppercase; letter-spacing: .5px; }
.post-card h3 { font-size: 18px; margin: 6px 0 8px; color: $(ink); line-height: 1.35; }
.post-card p.snippet { color: #64748b; font-size: 14px; line-height: 1.55; }

.post-full { background: #fff; border-radius: 16px; padding: 40px; box-shadow: 0 4px 20px rgba(0,0,0,.04); }
.post-full h1 { font-size: 36px; color: $(ink); line-height: 1.2; margin-bottom: 12px; }
.post-full .meta { color: #64748b; font-size: 14px; margin-bottom: 24px; }
.post-full .body { font-size: 17px; line-height: 1.75; color: #1e293b; }
.post-full .body p, .post-full .body ul, .post-full .body ol { margin: 16px 0; }
.post-full .body h2 { font-size: 24px; margin: 32px 0 12px; color: $(brand); }
.post-full .body h3 { font-size: 20px; margin: 24px 0 10px; }
.post-full .body img { border-radius: 10px; margin: 20px 0; }
.post-full .body a { color: $(accent); text-decoration: underline; }

.footer { background: #fff; border-top: 1px solid #e2e8f0; padding: 32px 24px; text-align: center; color: #64748b; font-size: 14px; margin-top: 60px; }

.blog-pager { text-align: center; margin-top: 32px; }
.blog-pager a { display: inline-block; padding: 10px 20px; background: $(brand); color: #fff; border-radius: 8px; margin: 0 6px; font-size: 14px; }

@media (max-width: 640px) {
  .hero { padding: 60px 20px; min-height: 320px; }
  .hero h1 { font-size: 32px; }
  .nav { display: none; }
}
